# M. O. Skarsten, George Drouillard, Hunter and Interpreter for Lewis and Clark and Fur Trader, 1807-1810,
# Glendale, Arthur H. Clark, 1964. PDF du Drive de l'auteur (HISTOIRE_LIVRES/DROUILLARD), relu le 19 novembre 2026 :
# chapitres sur les origines, le recrutement, la désertion de Reed, les Nez-Percés, les Pieds-Noirs et toute la seconde
# partie (traite avec Lisa, procès, Trois-Fourches). Préfixe SK64 ; pages de l'édition.
from commun import Corpus
S = "Skarsten, M. O. (1964), George Drouillard, Hunter and Interpreter for Lewis and Clark and Fur Trader, 1807-1810, Glendale, Arthur H. Clark"
C = Corpus('Recherches', 'SK64', S, page_fmt='p. {}')
F = C.F
G = ['George Drouillard']
F('01', "Détroit et Sandwich : la famille de Pierre Drouillard, interprète des Britanniques, et la belle-mère de George (1776-1809)", 'famille', '1776/1809', -83.05, 42.32, 'c', G + ['Pierre Drouillard', 'Angélique Descamps'],
  "George Drouillard est le fils d'un Canadien, Pierre Drouillard, interprète des Britanniques à Détroit, et d'une Shawnee. En 1776, Pierre épouse Angélique Descamps, dont il a plusieurs enfants ; George semble avoir été accueilli dans ce foyer et y avoir reçu quelque instruction. En 1809, il écrit de Saint-Louis à sa demi-sœur Marie-Louise, saluant « notre mère », ses frères et sœurs, Madame Maisonville et Madame Jacques Parent, de Détroit et de Sandwich. Tombé en disgrâce auprès des Britanniques après la cession de Détroit (1796), Pierre devient interprète des Américains en Ohio.",
  '18-22', "")
F('02', "Sandusky : Pierre Drouillard arrache Simon Kenton au bûcher (vers 1778)", 'evenement', '1778~', -82.71, 41.45, 'a', ['Pierre Drouillard', 'Simon Kenton'],
  "À Sandusky, Pierre Drouillard, père de George, trouve une bande d'Indiens prêts à brûler leur prisonnier américain, Simon Kenton, compagnon de Daniel Boone. Il intervient et obtient qu'on le lui remette. Kenton lui rendra la pareille en l'aidant à s'établir chez les Américains après 1796.",
  '21-22', "Skarsten ne date pas l'épisode ; la capture de Kenton date de 1778.")
F('03', "Cap-Girardeau : George Drouillard « du district du Cap-Girardeau », parent de Louis Lorimier (avant 1803)", 'personne', '1795~/1803', -89.52, 37.31, 'h', G + ['Louis Lorimier'],
  "Jeune, George suit les Shawnees de sa mère au Missouri. Il se dit « du district du Cap-Girardeau », poste espagnol commandé par Louis Lorimier. Un « M. Drewyer » qui habite le fort Massac est neveu de Lorimier : s'il est parent de George, celui-ci l'est aussi du commandant.",
  '20, 22', "Lien de parenté conjectural.")
F('04', "Fort Massac : Lewis engage George Drouillard comme interprète (11 novembre 1803)", 'personne', '1803-11-11/1804-02-11', -88.71, 37.15, 'c', G + ['Meriwether Lewis', 'William Graeter'],
  "Le 11 novembre 1803, au fort Massac sur l'Ohio, Lewis engage « George Drewyer » comme interprète indien à 25 dollars par mois ; l'agent militaire Swan lui avance trente dollars. Lewis l'envoie aussitôt recruter des hommes au Tennessee. Drouillard est inscrit au rôle de l'expédition le 1er janvier 1804 ; le 11 février, revenu au fort Massac « régler ses affaires », il y signe un billet de 301,63 dollars à William Graeter, qui le poursuivra en 1808.",
  '21, 23, 27-37', "")
F('05', "Cahokia : Drouillard amène huit recrues du Tennessee à Lewis (16 décembre 1803)", 'evenement', '1803-12-16/1803-12-17', -90.19, 38.57, 'c', G + ['Meriwether Lewis', 'William Clark'],
  "Drouillard arrive à Cahokia le 16 décembre 1803 avec huit hommes recrutés au Tennessee, à plus de deux cents milles. Lewis écrit le lendemain à Clark qu'il est un peu déçu, « il n'y a pas un chasseur parmi eux », et qu'il n'a pas encore conclu de « marché ferme » avec Drouillard ; il lui confie ses bagages et ses lettres pour Clark. Tout l'hiver, Drouillard porte les messages entre Lewis à Saint-Louis et Clark au camp de la rivière Wood.",
  '27-29', "")
F('06', "Village des Otos : Drouillard ramène le déserteur Moses Reed (août 1804)", 'evenement', '1804-08-07/1804-08-18', -96.4, 41.2, 'h', G + ['Moses Reed', 'La Liberté', 'Reuben Field', 'William Bratton', 'François Labiche'],
  "Après le conseil du 3 août avec les Otos, le soldat Moses Reed fait demi-tour sous prétexte d'un couteau oublié, et l'engagé La Liberté, envoyé chez les Otos, ne revient pas. Le 7 août, les capitaines dépêchent Drouillard, Reuben Field, Bratton et Labiche avec ordre de ramener Reed, de le tuer s'il résiste, de chercher La Liberté au village oto et d'inviter les chefs à une paix avec les Omahas et les Sioux. Drouillard ramène Reed, qui sera jugé et chassé de l'expédition.",
  '45-54', "Point hypothétique au village oto de la Platte.")
F('07', "Camp Chopunnish (Kamiah) : Drouillard interprète en signes de Clark chez les Nez-Percés (mai-juin 1806)", 'rencontre', '1806-05/1806-06-10', -116.03, 46.23, 'c', G + ['William Clark', 'Tunnachemootoolt', 'Twisted Hair'],
  "Au camp Chopunnish, Drouillard accompagne Clark chez le chef Tunnachemootoolt (Broken Arm), qui promet des guides pour la traversée des Bitterroots et remet deux calumets, l'un pour les Américains, l'autre pour la paix avec les Shoshones. En son absence, Lewis ne peut comprendre le message que lui apporte Twisted Hair. Drouillard et Reuben Field sont les coureurs les plus rapides de l'expédition aux jeux organisés avec les Nez-Percés. Le 10 juin, Drouillard ouvre la marche dans la neige des montagnes.",
  '207-210', "")
F('08', "Two Medicine : Drouillard et Lewis dans la tente des Piégans, puis le combat (26-27 juillet 1806)", 'evenement', '1806-07-26/1806-07-27', -112.85, 48.45, 'c', G + ['Meriwether Lewis', 'Joseph Field', 'Reuben Field'],
  "Au retour du camp Disappointment, sur le Cut Bank, Drouillard aperçoit le premier huit Indiens et trente chevaux. Ce sont des Piégans. Lewis et Drouillard passent la nuit dans leur tente de peaux, Drouillard servant d'interprète par signes ; à l'aube, Wolf Calf saisit le fusil posé sous le havresac de Drouillard pendant que d'autres prennent ceux des frères Field. Dans la lutte, Reuben Field poignarde un Piégan et Lewis en abat un autre.",
  '225-236', "")
F('09', "Embouchure de l'Osage : le déserteur Antoine Bissonnette abattu sur ordre de Lisa (14 mai 1807)", 'evenement', '1807-05-14/1807-05-15', -92.0, 38.6, 'c', G + ['Manuel Lisa', 'Antoine Bissonnette', 'Antoine Dubreuil', 'Benito Vasquez'],
  "La troupe de Lisa compte quarante-deux hommes, dont trente-sept Canadiens ; Drouillard y représente William Morrison et Pierre Ménard, de Kaskaskia, et Benito Vasquez est second. Au départ de l'embouchure de l'Osage, l'engagé Antoine Bissonnette, dit « Bazine », manque à l'appel. Lisa ordonne à Drouillard de le ramener « mort ou vif » ; il part avec Benito, tire, et revient dire qu'il l'a blessé. Lisa approuve : « c'est un coquin qui a eu ce qu'il méritait ». Bissonnette, atteint dans le dos, meurt le lendemain dans le canot qui l'emmène à Saint-Charles. Il avait caché ses couvertures à la rivière Aux Maries.",
  '252-253, 271-273', "Témoignage d'Antoine Dubreuil du 5 août 1808.")
F('10', "Fort Raymond (embouchure du Bighorn) : le premier poste américain du haut Missouri (octobre 1807)", 'commerce', '1807-10', -107.55, 46.15, 'c', G + ['Manuel Lisa', 'John Colter', 'Edward Rose'],
  "Après avoir intimidé Arikaras, Mandanes et Assiniboines à coups de pierriers, Lisa, conseillé par John Colter rencontré à l'embouchure de la Platte, bâtit en octobre 1807 son poste au confluent du Bighorn et de la Yellowstone : fort Raymond, ou fort Lisa, « le premier bâtiment élevé dans les limites de l'actuel Montana ». Edward Rose est envoyé traiter chez les Crows, qui obtiennent ses marchandises sans payer.",
  '255-259', "")
F('11', "Montagne Cedar et rivière Stinking Water : le premier voyage de Drouillard chez les Crows et les sources chaudes (hiver 1807-1808)", 'exploration', '1807-11/1808-01', -109.15, 44.5, 'a', G + ['John Colter'],
  "Parti à pied du fort Raymond, Drouillard remonte la Yellowstone, passe le Pompey's Pillar, visite un camp à l'embouchure du Pryor et un grand village crow sur la Clarks Fork, place correctement la Heart Mountain, puis passe deux jours chez les Crows près de la montagne Cedar, « montagne des Esprits », sur la Stinking Water (Shoshone). Les Crows lui parlent d'une grotte de sel et d'« établissements espagnols » au-delà des montagnes. Skarsten pense que Drouillard fut le premier à décrire à Clark les fumerolles et les eaux bouillantes du lieu qu'on appellera « l'enfer de Colter ». Il redescend jusqu'au confluent du Bighorn, où hivernent 280 loges.",
  '260-267', "")
F('12', "Little Bighorn, Rosebud et Tongue : le second voyage de Drouillard en quête de clients (printemps 1808)", 'exploration', '1808-03/1808-04', -107.2, 45.3, 'h', G,
  "Au printemps 1808, Drouillard repart à pied du fort Raymond vers le sud : il remonte le Little Bighorn, où il note d'excellents terrains à castors, passe au Rosebud (qu'il prend pour un affluent de la Tongue et appelle Minna-e-sa), décrit un lac circulaire au pied d'une haute crête, gagne la Tongue et l'Otter Creek, visite plusieurs camps indiens et rentre par les montagnes « Chatish ou Woolf teeth » : quinze jours et plus de deux cents milles, tout près du futur champ de bataille de Custer.",
  '267-270', "Itinéraire reconstitué d'après la carte que Clark dressa avec Drouillard ; point hypothétique.")
F('13', "Saint-Louis : procès et acquittement de Drouillard pour le meurtre de Bissonnette (23 septembre 1808)", 'evenement', '1808-08-06/1808-09-23', -90.19, 38.627, 'c', G + ['Jean-Baptiste-Charles Lucas', 'Auguste Chouteau', 'Edward Hempstead', 'Rufus Easton', 'William C. Carr', 'John Scott', 'George Shannon', 'Thomas F. Riddick'],
  "Rentré à Saint-Louis début août 1808, Drouillard est arrêté le 6 sur ordre du juge de paix Thomas F. Riddick. Le 23 septembre, la cour d'oyer et terminer, présidée par J.-B.-C. Lucas avec Auguste Chouteau comme juge associé, l'entend : l'avocat général John Scott plaide le meurtre ; Hempstead, Easton et Carr soutiennent que la désertion avec vol d'équipement justifiait l'acte et que la faute revient à Lisa. Le jury, où siège un George Shannon, sans doute l'ancien de l'expédition, rend en quinze minutes un verdict de non-culpabilité. Drouillard vend ensuite à Riddick et Alexander McNair, pour 1 300 dollars, sa concession de terre et celles achetées à Whitehouse et Collins ; ses renseignements servent à Clark pour sa carte de la Yellowstone.",
  '261, 271-279, 339', "")
F('14', "Saint-Louis : la lettre de Drouillard à sa demi-sœur de Détroit (23 mai 1809)", 'personne', '1809-05-23', -90.19, 38.627, 'c', G + ['Pascal Cerré'],
  "Avant de repartir avec la Compagnie de fourrures du Missouri, Drouillard écrit à sa demi-sœur Marie-Louise à Détroit : faute d'argent, il n'a pu venir l'hiver passé et ne pense pas revenir du haut Missouri avant trois ans ; qu'on lui écrive aux soins de M. Pascal Cerré. Il revient sur la mort de Bissonnette, commise « sans malice, haine ni mauvaise intention », par irréflexion, et « encouragé et pressé par mon associé, Manuel Lisa, qui doit être considéré aussi coupable que moi ».",
  '19, 274-279', "")
F('15', "Rivière Jefferson, près des Trois-Fourches : « Je suis trop Indien pour être pris par des Indiens », la mort de Drouillard (mai 1810)", 'evenement', '1810-05', -111.62, 45.85, 'c', G + ['Thomas James', 'Pierre Ménard'],
  "Après l'attaque du 12 avril 1810 contre les trappeurs de la Jefferson, le poste des Trois-Fourches vit dans la peur. Exaspéré par la timidité des hommes, Drouillard part seul tendre ses pièges deux milles en amont du camp et rapporte six castors ; à James qui le met en garde, il répond : « Je suis trop Indien pour être pris par des Indiens. » Un matin de mai, parti avec deux Delawares, il est surpris par les Pieds-Noirs ; James retrouve les deux Delawares percés de lances, puis, cent cinquante verges plus loin, Drouillard et son cheval : il avait combattu en cercle, à cheval puis derrière sa monture, avant d'être décapité et mis en pièces.",
  '297-316', "Récit de Thomas James, cité par Skarsten.")
fiches = C.fiches
